(async () => {
  // CT-001: API 错误响应精确 Content-Type
  const bad = await start({
    port: 0,
    dataPath: path.join(ROOT, 'tests', 'backend', 'fixtures', 'broken.json'),
    staticRoot: path.join(ROOT, 'tests', 'backend', 'fixtures', 'static'),
  });
  const errRes = await fetch(bad.origin + '/api/levels');
  assert.equal(errRes.status, 500);
  assert.equal(errRes.headers.get('content-type'), 'application/json; charset=utf-8');
  const errBody = await errRes.json();
  assert.equal(errBody.code, 'LEVEL_DATA_UNAVAILABLE');
  await bad.stop();

  const ok = await start({
    port: 0,
    dataPath: path.join(ROOT, 'data', 'levels.json'),
    staticRoot: path.join(ROOT, 'tests', 'backend', 'fixtures', 'static'),
  });

  // CT-003: 静态资源按路径返回内容与精确 Content-Type
  const idx = await fetch(ok.origin + '/');
  assert.equal(idx.status, 200);
  assert.equal(idx.headers.get('content-type'), 'text/html; charset=utf-8');
  assert.match(await idx.text(), /backend-static-index/);

  const css = await fetch(ok.origin + '/styles.css');
  assert.equal(css.headers.get('content-type'), 'text/css; charset=utf-8');
  assert.match(await css.text(), /teal/);

  const js = await fetch(ok.origin + '/app.js');
  assert.equal(js.headers.get('content-type'), 'text/javascript; charset=utf-8');
  assert.match(await js.text(), /backend-static-app/);

  // API 正常响应 Content-Type
  const api = await fetch(ok.origin + '/api/levels');
  assert.equal(api.headers.get('content-type'), 'application/json; charset=utf-8');
  assert.equal((await api.json()).length, 5);

  // CT-002: stop 返回 Promise 且释放端口监听
  const stopResult = ok.stop();
  assert.ok(stopResult instanceof Promise, 'stop 应返回 Promise');
  await stopResult;
  let refused = false;
  try {
    await fetch(ok.origin + '/', { signal: AbortSignal.timeout(2000) });
  } catch (e) {
    refused = true;
  }
  assert.ok(refused, 'stop 后新连接应被拒绝（监听已释放）');
  console.log('CT-001 PASS, CT-002 PASS, CT-003 PASS');
})().catch((e) => {
  console.error('CONTRACT VERIFY FAILED: ' + e.message);
  process.exit(1);
});
EOF
