const { start } = require('./server/server.js');
const assert = require('node:assert/strict');
(async () => {
  const instance = await start({ port: 0 });
  try {
    const page = await fetch(instance.origin + '/');
    assert.equal(page.status, 200);
    assert.match(page.headers.get('content-type'), /text\/html/);
    const html = await page.text();
    assert.match(html, /id=\"level-loading\"/);
    assert.match(html, /id=\"level-list\"/);
    assert.match(html, /id=\"level-error\"/);
    const script = await fetch(instance.origin + '/level-select.js');
    assert.equal(script.status, 200);
    assert.match(script.headers.get('content-type'), /text\/javascript/);
    const api = await fetch(instance.origin + '/api/levels');
    assert.equal(api.status, 200);
    const levels = await api.json();
    assert.equal(levels.length, 5);
    console.log('SMOKE OK: / 200 text/html + 3 containers; /level-select.js 200 text/javascript; /api/levels 200 5 levels');
  } finally {
    await instance.stop();
  }
})().catch((e) => { console.error('SMOKE FAIL:', e.message); process.exit(1); });
"

