(async () => {
  // CT-001 输入契约复验：API 错误响应精确 Content-Type
  const bad = await start({
    port: 0,
    dataPath: path.join(ROOT, 'tests', 'backend', 'fixtures', 'broken.json'),
    staticRoot: path.join(ROOT, 'web'),
  });
  const errRes = await fetch(bad.origin + '/api/levels');
  assert.equal(errRes.status, 500);
  assert.equal(errRes.headers.get('content-type'), 'application/json; charset=utf-8');
  await bad.stop();

  // 集成冒烟：staticRoot 指向 web 时页面与脚本同源可达
  const ok = await start({
    port: 0,
    dataPath: path.join(ROOT, 'data', 'levels.json'),
    staticRoot: path.join(ROOT, 'web'),
  });
  const idx = await fetch(ok.origin + '/');
  assert.equal(idx.status, 200);
  const html = await idx.text();
  assert.match(html, /src="\/level-select\.js"/, '页面应同源引用 level-select.js');
  assert.match(html, /id="level-loading"/);
  assert.match(html, /id="level-list"/);
  assert.match(html, /id="level-error"/);

  const script = await fetch(ok.origin + '/level-select.js');
  assert.equal(script.status, 200);
  assert.match(script.headers.get('content-type'), /text\/javascript/);
